/**
 * Home page concepts (workspace/homeConcepts.ts) on one app: the Clean Cart slice's app (eval 1), regenerated by
 * FlowCode, with each concept applied to its own copy. Every concept's layout and tokens must be implemented as
 * rendered, the concepts' Home pages must differ in structure (the opening, the section order, how categories and
 * entries flow), not only in style, and the functional journey must still pass on each. Screenshots are for the
 * person to choose a direction from; nothing here judges which is better. Needs the recorded workspace and a browser.
 */
import fs from "node:fs";
import { createHash } from "node:crypto";
import os from "node:os";
import path from "node:path";
import { spawn, type ChildProcess } from "node:child_process";
import { afterAll, describe, expect, it } from "vitest";
import { chromium, type Browser } from "playwright";
import { journeyPlan, runJourney } from "../src/quality/appJourney.js";
import { measureDesign, measureLayout, measureStructure, specImplementation, specMeasureTokens, type MeasuredStructure } from "../src/quality/designSpecCheck.js";
import { applyDesignSpec, type DesignSpec } from "../src/workspace/designSpec.js";
import { HOME_CONCEPTS } from "../src/workspace/homeConcepts.js";
import { prdNamedRecords, prdSampleSection, resolveScreenAliases, type AppModel } from "../src/orchestrator/appModel.js";
import { declaredScreens } from "../src/orchestrator/screenPlan.js";
import { mergeRecords, prdFixtureRows } from "../src/orchestrator/recordIdentity.js";
import { appFiles } from "../src/orchestrator/appFiles.js";
import { syncedLibraryCss } from "../src/orchestrator/sectionRecipes.js";
import { makeApp } from "./helpers.js";

const REPO = path.resolve(import.meta.dirname, "../../..");
const RECORDED = path.join(REPO, ".flowcode-data/workspaces/clean-cart-slice-eval-1-9b1947");
const PRD = fs.readFileSync(path.join(REPO, "docs/handoff/slice/clean-cart-slice-prd.md"), "utf8");
const MODEL = JSON.parse(fs.readFileSync(path.join(import.meta.dirname, "fixtures/apps/eval1-app-model.json"), "utf8")) as AppModel;
const SCREENS = declaredScreens(PRD);
const NAMED = prdNamedRecords(prdSampleSection(PRD));
/** Where screenshots and measurements go for the person's review, when asked for (FLOWCODE_SPEC_SHOTS=<dir>). */
const SHOTS = process.env.FLOWCODE_SPEC_SHOTS;

const prdRows = (e: AppModel["entities"][number]) => prdFixtureRows(e, prdSampleSection(PRD));
const seed = Object.fromEntries(MODEL.entities.map((e) => [e.key, mergeRecords(e, [], MODEL.seed[e.key] ?? [], { prdRows: prdRows(e) }).rows]));
const FIXED = resolveScreenAliases({ ...MODEL, seed }, SCREENS);

/** A copy of the regenerated app (node_modules linked), as FlowCode writes it from the model. */
function copyApp(model: AppModel = FIXED): string {
  const root = fs.mkdtempSync(path.join(os.tmpdir(), "fc-concept-"));
  const walk = (from: string, to: string) => {
    for (const e of fs.readdirSync(from, { withFileTypes: true })) {
      if (["node_modules", "dist", ".git"].includes(e.name)) continue;
      const s = path.join(from, e.name);
      const d = path.join(to, e.name);
      if (e.isDirectory()) (fs.mkdirSync(d, { recursive: true }), walk(s, d));
      else fs.copyFileSync(s, d);
    }
  };
  walk(RECORDED, root);
  fs.symlinkSync(path.join(RECORDED, "node_modules"), path.join(root, "node_modules"), "junction");
  for (const f of appFiles(model).filter((f) => !f.path.startsWith("src/screens/"))) (fs.mkdirSync(path.dirname(path.join(root, f.path)), { recursive: true }), fs.writeFileSync(path.join(root, f.path), f.content));
  const css = syncedLibraryCss(root);
  if (css !== undefined) fs.writeFileSync(path.join(root, "src/styles/library.css"), css);
  return root;
}

const servers: ChildProcess[] = [];
let browser: Browser | undefined;
async function serve(root: string, port: number): Promise<string> {
  const p = spawn(process.execPath, [path.join(root, "node_modules/vite/bin/vite.js"), "--port", String(port), "--strictPort", "--host", "127.0.0.1"], { cwd: root, stdio: ["ignore", "pipe", "pipe"] });
  servers.push(p);
  const url = `http://127.0.0.1:${port}/`;
  for (let i = 0; i < 120; i++) {
    if (await fetch(url).then((r) => r.ok, () => false)) return url;
    await new Promise((r) => setTimeout(r, 500));
  }
  throw new Error("vite didn't start");
}

async function render(spec: DesignSpec, port: number) {
  const root = copyApp();
  const { app } = makeApp();
  const project = app.projects.create({ name: `Concept ${spec.id}`, workspacePath: root });
  const t0 = performance.now();
  const application = applyDesignSpec(app.projects.jail(project), app.ops, { projectId: project.id, runId: "concept_regression" }, spec, { frameCss: "src/styles/components.css", screens: [], model: FIXED });
  const applyMs = performance.now() - t0;
  const url = await serve(root, port);
  browser ??= await chromium.launch();
  const page = await browser.newPage({ viewport: { width: 1440, height: 900 } });
  const errs: string[] = [];
  page.on("pageerror", (e) => errs.push(e.message));
  page.on("console", (m) => m.type() === "error" && errs.push(m.text()));
  await page.goto(url, { waitUntil: "networkidle" });
  if (SHOTS) fs.mkdirSync(SHOTS, { recursive: true }), fs.writeFileSync(path.join(SHOTS, `${spec.id}-errors.txt`), errs.join("\n"));
  await page.evaluate(() => document.fonts.ready);
  const t1 = performance.now();
  const measured = await measureDesign(page, specMeasureTokens(spec));
  const layout = await measureLayout(page);
  const structure = await measureStructure(page);
  const verifyMs = performance.now() - t1;
  if (SHOTS) (fs.mkdirSync(SHOTS, { recursive: true }), await page.screenshot({ path: path.join(SHOTS, `${spec.id}.png`), fullPage: true }));
  await page.close();
  const jp = await browser.newPage({ viewport: { width: 1280, height: 860 } });
  const t2 = performance.now();
  const journey = await runJourney(jp, url, journeyPlan(application.model ?? FIXED, SCREENS, NAMED));
  const journeyMs = performance.now() - t2;
  await jp.close();
  const results = specImplementation(spec, measured, { requirements: application.requirements, layout, structure });
  return { spec, application, results, layout, structure, timings: { applyMs, verifyMs, journeyMs }, journeyFailed: journey.steps.filter((s) => !s.ok).map((s) => `${s.step}: ${s.detail}`) };
}

afterAll(async () => {
  await browser?.close();
  for (const p of servers) p.kill();
});

/** A structural signature from geometry alone: what a person sees as the page's layout, independent of colours and fonts. */
const signature = (st: MeasuredStructure) => ({
  sidebar: st.sidebar ? "side column" : "full width",
  opening: st.opening >= 0.45 ? "tall opening" : st.opening >= 0.2 ? "medium opening" : "short opening",
  groups: `${st.groups} groups of like items`,
  firstRow: `${st.firstRow} in the first row`,
  blocks: `${st.blocks} blocks`,
});

describe.skipIf(process.env.FLOWCODE_SKIP_BROWSER === "1" || !fs.existsSync(path.join(RECORDED, "node_modules")))("Home page concepts on the same app", () => {
  it("each renders its own layout and look, they differ in structure, and the journey passes on each", async () => {
    const out = [];
    for (const [i, c] of HOME_CONCEPTS.entries()) out.push(await render(c, 5361 + i));
    if (SHOTS) fs.writeFileSync(path.join(SHOTS, "concepts.json"), JSON.stringify(out.map((o) => ({ id: o.spec.id, results: o.results, layout: o.layout, structure: o.structure, signature: signature(o.structure), timings: o.timings, journeyFailed: o.journeyFailed })), null, 2));

    for (const o of out) {
      // Tokens and the library layout are implemented as rendered; nothing is left to a coder.
      expect(o.results.filter((r) => r.status !== "implemented").map((r) => `${o.spec.id} ${r.id}: ${r.evidence}`)).toEqual([]);
      expect(o.results.find((r) => r.id === "home-layout")?.by).toBe("library");
      expect(o.journeyFailed).toEqual([]);
    }
    // Each renders its own library page, and every pair differs in structure (geometry) on at least two of: a side
    // column, the opening's height, how many groups of like items, how many sit in the first group's row, the number of blocks.
    expect(out.map((o) => o.structure.design)).toEqual(HOME_CONCEPTS.map((c) => c.composition.home!.design));
    const sigs = out.map((o) => signature(o.structure));
    for (let a = 0; a < sigs.length; a++)
      for (let b = a + 1; b < sigs.length; b++) {
        const differ = (Object.keys(sigs[a]!) as Array<keyof (typeof sigs)[number]>).filter((k) => sigs[a]![k] !== sigs[b]![k]);
        expect(differ.length, `${out[a]!.spec.id} vs ${out[b]!.spec.id}: ${JSON.stringify([sigs[a], sigs[b]])}`).toBeGreaterThanOrEqual(2);
      }
  }, 600_000);

  it("applying a concept keeps the app's own content and behaviour: it is the app's data in a library page, not a template", async () => {
    // A product renamed in the app model: a template would still show its own sample content; the concept shows this.
    const RENAMED = "Morning Oat Drink";
    const top = FIXED.seed.product!.find((r) => r.name === "Oat Milk Original")!;
    const model: AppModel = { ...FIXED, seed: { ...FIXED.seed, product: FIXED.seed.product!.map((r) => (r.id === top.id ? { ...r, name: RENAMED } : r)) } };
    const hashes = (root: string) => {
      const out: Record<string, string> = {};
      const walk = (dir: string) => {
        for (const e of fs.readdirSync(path.join(root, dir), { withFileTypes: true })) {
          const rel = path.posix.join(dir, e.name);
          if (["node_modules", "dist", ".git", "public"].includes(e.name)) continue;
          if (e.isDirectory()) walk(rel);
          else out[rel] = createHash("sha256").update(fs.readFileSync(path.join(root, rel))).digest("hex");
        }
      };
      walk(".");
      return out;
    };
    // What applying a concept may change: the look (tokens, surface style), the Home screen and the frame's file, and
    // the library pages and styles it brings. Everything else (data, store, look-up layer, routes, every other page) stays.
    const mayChange = (p: string) => /^src\/(styles\/|sections\/)/.test(p) || ["src/screens/LandingScreen.tsx", "src/App.tsx", "src/main.tsx"].includes(p);
    for (const [i, spec] of HOME_CONCEPTS.entries()) {
      const root = copyApp(model);
      const before = hashes(root);
      const { app } = makeApp();
      const project = app.projects.create({ name: `Keep ${spec.id}`, workspacePath: root });
      applyDesignSpec(app.projects.jail(project), app.ops, { projectId: project.id, runId: "concept_keep" }, spec, { frameCss: "src/styles/components.css", screens: [], model });
      const after = hashes(root);
      const changed = Object.keys(after).filter((p) => before[p] !== after[p]);
      expect(changed.filter((p) => !mayChange(p)), spec.id).toEqual([]);
      expect(Object.keys(before).filter((p) => !(p in after)), `${spec.id}: nothing removed`).toEqual([]);
      for (const p of ["src/app/schema.ts", "src/app/store.ts", "src/app/lookup.ts", "src/app/routes.ts", "src/screens/CatalogScreen.tsx", "src/screens/ProductScreen.tsx", "src/screens/SavedScreen.tsx"]) expect(after[p], `${spec.id}: ${p} kept`).toBe(before[p]);

      const url = await serve(root, 5371 + i);
      browser ??= await chromium.launch();
      const page = await browser.newPage({ viewport: { width: 1440, height: 900 } });
      const errors: string[] = [];
      page.on("pageerror", (e) => errors.push(e.message));
      await page.goto(url, { waitUntil: "networkidle" });
      const main = page.locator("main").first();
      const text = await main.innerText();
      // The app's own content: its name, its (renamed) most liked product and its categories; none of the library
      // page's sample content (its sample is children's books).
      expect(text, spec.id).toContain(model.product);
      expect(text, spec.id).toContain(RENAMED);
      expect(text, spec.id).not.toContain("Oat Milk Original");
      for (const c of ["Beverages", "Bakery", "Dairy"]) expect(text, `${spec.id}: ${c}`).toContain(c);
      expect(text, spec.id).not.toMatch(/Morning Songs|Shelf Finder|libraries near/i);
      // Its behaviour: a product on Home opens that product's own page; the Home search goes to the catalog with the
      // words; a save control on Home is the app's own (the visitor is asked to sign in, as everywhere in the app).
      await main.getByRole("button", { name: RENAMED, exact: true }).first().click();
      await page.waitForTimeout(400);
      expect(await page.evaluate(() => location.hash), spec.id).toBe(`#/product/${encodeURIComponent(top.id)}`);
      expect(await page.locator("main").first().innerText()).toContain(RENAMED);
      await page.goto(url, { waitUntil: "networkidle" });
      const box = page.locator("main input[type=search]").first();
      await box.fill("oat");
      await box.press("Enter");
      await page.waitForTimeout(400);
      expect(await page.evaluate(() => location.hash), `${spec.id}: search`).toMatch(/^#\/catalog\/q(=|%3D)oat$/);
      await page.goto(url, { waitUntil: "networkidle" });
      const save = page.locator("main").getByRole("button", { name: /^save\b/i }).first();
      expect(await save.count(), `${spec.id}: a save control on Home`).toBeGreaterThan(0);
      expect(await save.getAttribute("aria-pressed"), spec.id).toBe("false");
      expect(errors, spec.id).toEqual([]);
      await page.close();
    }
  }, 600_000);
});
